using UnityEngine;using UnityEditor;using UnityEditor.Animations;using UnityEditor.SceneManagement;using System;using System.IO;using System.Linq;using System.Collections.Generic;using WitchPlayground;
public static class RollDirectionFix {
 public static void Run(){EditorSceneManager.OpenScene("Assets/Scenes/MoonlitForest.unity");var p=UnityEngine.Object.FindAnyObjectByType<WitchPlayer>();var roster=p.GetComponent<HeroRoster>();var report=new List<string>();for(int hero=0;hero<3;hero++){var anim=roster.animators[hero];var ac=(AnimatorController)anim.runtimeAnimatorController;var state=ac.layers[0].stateMachine.states.First(s=>s.state.name=="Roll").state;var src=(AnimationClip)state.motion;var rootBinding=AnimationUtility.GetCurveBindings(src).First(b=>b.propertyName=="m_LocalRotation.w"&&(b.path.Split('/').Last().ToLower().EndsWith("root")));var root=anim.transform.Find(rootBinding.path);src.SampleAnimation(anim.gameObject,0);var zero=root.localRotation;var worldZero=root.rotation;src.SampleAnimation(anim.gameObject,src.length*.25f);var delta=root.rotation*Quaternion.Inverse(worldZero);delta.ToAngleAxis(out float angle,out Vector3 axis);if(angle>180)angle-=360;float forward=angle*Vector3.Dot(axis,p.transform.right);report.Add("Hero "+hero+" original forward roll degrees at 25%: "+forward+"; root="+rootBinding.path);
  if(forward<0){var clip=UnityEngine.Object.Instantiate(src);clip.name=roster.ClassName(hero)+" Forward Roll";var curves=new[]{new AnimationCurve(),new AnimationCurve(),new AnimationCurve(),new AnimationCurve()};for(int i=0;i<=60;i++){float t=src.length*i/60;src.SampleAnimation(anim.gameObject,t);var value=zero*Quaternion.Inverse(Quaternion.Inverse(zero)*root.localRotation);curves[0].AddKey(t,value.x);curves[1].AddKey(t,value.y);curves[2].AddKey(t,value.z);curves[3].AddKey(t,value.w);}for(int i=0;i<4;i++){var b=rootBinding;b.propertyName="m_LocalRotation."+"xyzw"[i];AnimationUtility.SetEditorCurve(clip,b,curves[i]);}clip.EnsureQuaternionContinuity();string path="Assets/Animations/ForwardRoll"+hero+".anim";var old=AssetDatabase.LoadAssetAtPath<AnimationClip>(path);if(old){EditorUtility.CopySerialized(clip,old);UnityEngine.Object.DestroyImmediate(clip);clip=old;}else AssetDatabase.CreateAsset(clip,path);state.motion=clip;EditorUtility.SetDirty(ac);src=clip;}
  src.SampleAnimation(anim.gameObject,0);worldZero=root.rotation;src.SampleAnimation(anim.gameObject,src.length*.25f);delta=root.rotation*Quaternion.Inverse(worldZero);delta.ToAngleAxis(out angle,out axis);if(angle>180)angle-=360;forward=angle*Vector3.Dot(axis,p.transform.right);report.Add("Hero "+hero+" corrected forward degrees: "+forward);if(forward<=0)throw new Exception("Roll direction was not forward");}
  AssetDatabase.SaveAssets();Directory.CreateDirectory("Verification");File.WriteAllLines("Verification/roll-direction.txt",report);foreach(var line in report)Debug.Log(line);
 }
}
